import{_ as n,C as s,o as t,c as o,a3 as a,b as d,w as r,a as c,E as l,a2 as p}from"./chunks/framework.DQ-7HQaQ.js";const S=JSON.parse('{"title":"System architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/overview.md","filePath":"architecture/overview.md","lastUpdated":1794433168000}'),u={name:"architecture/overview.md"};function h(m,e,v,b,f,g){const i=s("Mermaid");return t(),o("div",null,[e[1]||(e[1]=a('<h1 id="system-architecture" tabindex="-1">System architecture <a class="header-anchor" href="#system-architecture" aria-label="Permalink to &quot;System architecture&quot;">​</a></h1><p><span class="status-label">DRAFT · DESIGN BASELINE</span></p><p>Deliver fast, grounded answers from a versioned document corpus. Keep document enrichment outside the live answer path and publish useful retrieval capabilities as they become ready. Performance is an end-to-end property: model processing, retrieval, queueing, network placement, and browser work all contribute.</p><h2 id="system-boundaries" tabindex="-1">System boundaries <a class="header-anchor" href="#system-boundaries" aria-label="Permalink to &quot;System boundaries&quot;">​</a></h2>',4)),(t(),d(p,null,{default:r(()=>[l(i,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TB%0A%20%20UI%5B%22SvelteKit%20browser%20interface%22%5D%20%3C--%3E%7C%22HTTP%20commands%20%2F%20SSE%22%7C%20CHAT%5B%22Rust%20chat%20service%22%5D%0A%20%20SSR%5B%22SvelteKit%20initial%20rendering%22%5D%20--%3E%20UI%0A%20%20CHAT%20--%3E%20RET%5B%22Retrieval%20application%20boundary%22%5D%0A%20%20RET%20--%3E%20DB%5B%22SQLite%20candidate%3A%20FTS5%20%2F%20vectors%20%2F%20graph%22%5D%0A%20%20CHAT%20%3C--%3E%7C%22Generation%20%2F%20cancellation%20where%20supported%22%7C%20MODEL%5B%22Model%20endpoint%22%5D%0A%20%20ORCH%5B%22One%20durable%20DAG%20orchestrator%22%5D%20--%3E%20NLP%5B%22Parsing%20and%20NLP%20workers%22%5D%0A%20%20NLP%20--%3E%20WRITER%5B%22Index%20publication%20owner%22%5D%0A%20%20WRITER%20--%3E%20DB%0A%20%20WRITER%20--%3E%20EVENTS%5B%22NATS%20%2F%20JetStream%20domain%20events%22%5D%0A%20%20EVENTS%20--%3E%20CHAT%0A%20%20SOURCE%5B%22Document%20revisions%22%5D%20--%3E%20ORCH%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>These are responsibility boundaries, not a requirement to deploy every box separately. Start with the fewest processes that preserve resource isolation and failure ownership. Database locality and model placement must be tested before adding service hops.</p><h2 id="conversation-path" tabindex="-1">Conversation path <a class="header-anchor" href="#conversation-path" aria-label="Permalink to &quot;Conversation path&quot;">​</a></h2><p>The browser submits an idempotent message command. Rust authorizes access, creates a run, retrieves eligible evidence, builds bounded context, and streams model output as structured events. One authoritative run owner decides ordering, cancellation, completion, and failure. UI event order is scoped by run and attempt.</p><p>SvelteKit may render the initial page and a bounded history snapshot. Active tokens travel directly from Rust to the browser. No frontend server proxy is required in that path. The snapshot includes a checkpoint per resumable run so the client can catch up without a replay/live subscription gap; cursors are scoped to that run and attempt.</p><p>Direct SSE is the default. A retained run-output log and separate generation workers are justified if independent generation, multiple viewers, or cross-device catch-up become required. Replaying recorded text does not resume a failed inference process.</p><h2 id="knowledge-path" tabindex="-1">Knowledge path <a class="header-anchor" href="#knowledge-path" aria-label="Permalink to &quot;Knowledge path&quot;">​</a></h2><p>BM25 and vector retrieval produce candidates over eligible document revisions. Combine ranks, expand selected graph relationships within explicit bounds, optionally rerank, and fetch original evidence. Every result carries document version and source anchors. Entity linking and graph traversal complement lexical and semantic search.</p><p>SQLite is a candidate for local retrieval, not an approved distributed database. <a href="/knowledge-lab/architecture/retrieval">Retrieval storage</a> describes extension capabilities, single-writer constraints, filtering correctness, and replacement seams.</p><h2 id="ingestion-path" tabindex="-1">Ingestion path <a class="header-anchor" href="#ingestion-path" aria-label="Permalink to &quot;Ingestion path&quot;">​</a></h2><p>A source revision creates a durable workflow. Parsing preserves structure and source locations. Retrieval chunks and larger extraction windows support different tasks. Embeddings and lexical indexing can progress independently of entity resolution, claim validation, and augmentation.</p><p>The orchestrator owns dependencies, retries, and readiness. NATS carries appropriate boundary events; it does not become a second scheduler. If the chosen orchestrator provides task queues, use its own execution protocol for those activities.</p><h2 id="principles-carried-into-this-draft" tabindex="-1">Principles carried into this draft <a class="header-anchor" href="#principles-carried-into-this-draft" aria-label="Permalink to &quot;Principles carried into this draft&quot;">​</a></h2><ol><li>Core evidence and run policies do not import Axum, SQLite, NATS, or an orchestration SDK.</li><li>Adapter contracts expose filtering, approximate-search, cancellation, and snapshot limitations.</li><li>One owner governs each state machine and one publication rule selects current artifacts.</li><li>Buffers, retrieval fanout, graph expansion, background compute, and retry budgets are bounded.</li><li>Source claims, resolution decisions, and generated augmentations remain distinguishable.</li></ol><p>These constraints respond to the <a href="/knowledge-lab/reviews/">three design reviews</a>. They are requirements for implementation and future tests, rather than evidence that an implementation already satisfies them.</p>',14))])}const T=n(u,[["render",h]]);export{S as __pageData,T as default};
